// NOTE: Assertions have been autogenerated by utils/update_cc_test_checks.py UTC_ARGS: --version 6
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -O2 -emit-llvm %s -o - | FileCheck --check-prefix=O2 %s
// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -O0 -emit-llvm %s -o - | FileCheck --check-prefix=O0 %s

// CGStmt.cpp emits an exact register-or-memory ("rm"/"mr") output directly
// (by value, no alloca) above -O0, the same as a plain "=r" output, and
// leaves the register-vs-memory decision -- and, if needed, the fallback to
// memory -- to the backend (TargetLowering::MayFoldRegister,
// RegAllocFast's inline asm folding). At -O0 it keeps the historical
// indirect (alloca + out-parameter) form, matching every other memory-
// capable constraint: MayFoldRegister is disabled at -O0 too (the fast
// allocator's own on-demand folding is what -O0 relies on instead), so
// there would be nothing gained by taking the direct path there, and the
// indirect form is what every codegen path has always been tested against.
// O2-LABEL: define dso_local i64 @test_rm_output(
// O2-SAME: ) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// O2-NEXT:  [[ENTRY:.*:]]
// O2-NEXT:    [[TMP0:%.*]] = tail call i64 asm sideeffect "# $0", "=rm,~{dirflag},~{fpsr},~{flags}"() #[[ATTR3:[0-9]+]], !srcloc [[META6:![0-9]+]]
// O2-NEXT:    ret i64 [[TMP0]]
//
// O0-LABEL: define dso_local i64 @test_rm_output(
// O0-SAME: ) #[[ATTR0:[0-9]+]] {
// O0-NEXT:  [[ENTRY:.*:]]
// O0-NEXT:    [[OUT:%.*]] = alloca i64, align 8
// O0-NEXT:    call void asm sideeffect "# $0", "=*rm,~{dirflag},~{fpsr},~{flags}"(ptr elementtype(i64) [[OUT]]) #[[ATTR2:[0-9]+]], !srcloc [[META1:![0-9]+]]
// O0-NEXT:    [[TMP0:%.*]] = load i64, ptr [[OUT]], align 8
// O0-NEXT:    ret i64 [[TMP0]]
//
unsigned long test_rm_output(void) {
  unsigned long out;
  __asm__ volatile("# %0" : "=rm"(out));
  return out;
}

// The tied "+rm" case is the one this file exists to cover: before, a tied
// register-or-memory output kept an indirect alloca even at -O2 with no
// register pressure at all, because CGStmt.cpp's direct-vs-indirect
// decision didn't recognize "rm" as different from a plain "m" -- so a
// read-modify-write asm operand paid for a real memory round trip it never
// needed.
// O2-LABEL: define dso_local i64 @test_tied_rm_output(
// O2-SAME: i64 noundef [[LEN:%.*]]) local_unnamed_addr #[[ATTR0]] {
// O2-NEXT:  [[ENTRY:.*:]]
// O2-NEXT:    [[TMP0:%.*]] = tail call i64 asm sideeffect "incq $0", "=rm,0,~{dirflag},~{fpsr},~{flags}"(i64 [[LEN]]) #[[ATTR3]], !srcloc [[META7:![0-9]+]]
// O2-NEXT:    ret i64 [[TMP0]]
//
// O0-LABEL: define dso_local i64 @test_tied_rm_output(
// O0-SAME: i64 noundef [[LEN:%.*]]) #[[ATTR0]] {
// O0-NEXT:  [[ENTRY:.*:]]
// O0-NEXT:    [[LEN_ADDR:%.*]] = alloca i64, align 8
// O0-NEXT:    store i64 [[LEN]], ptr [[LEN_ADDR]], align 8
// O0-NEXT:    [[TMP0:%.*]] = load i64, ptr [[LEN_ADDR]], align 8
// O0-NEXT:    call void asm sideeffect "incq $0", "=*rm,0,~{dirflag},~{fpsr},~{flags}"(ptr elementtype(i64) [[LEN_ADDR]], i64 [[TMP0]]) #[[ATTR2]], !srcloc [[META2:![0-9]+]]
// O0-NEXT:    [[TMP1:%.*]] = load i64, ptr [[LEN_ADDR]], align 8
// O0-NEXT:    ret i64 [[TMP1]]
//
unsigned long test_tied_rm_output(unsigned long len) {
  __asm__ volatile("incq %0" : "+rm"(len));
  return len;
}

// The output's address escaping to another call must still force a real
// store to memory before that call, regardless of the register preference
// for the asm's own operand. This exercises pre-existing, general
// "materialize to memory only when something forces it" logic, not
// anything specific to the "rm" constraint -- included here as a guard
// against a regression that would make the escaped address diverge from
// what the asm actually wrote.
void observe(unsigned long *p);
// O2-LABEL: define dso_local i64 @test_rm_output_escapes(
// O2-SAME: ) local_unnamed_addr #[[ATTR0]] {
// O2-NEXT:  [[ENTRY:.*:]]
// O2-NEXT:    [[OUT:%.*]] = alloca i64, align 8
// O2-NEXT:    call void @llvm.lifetime.start.p0(ptr nonnull [[OUT]]) #[[ATTR3]]
// O2-NEXT:    [[TMP0:%.*]] = tail call i64 asm sideeffect "# $0", "=rm,~{dirflag},~{fpsr},~{flags}"() #[[ATTR3]], !srcloc [[META8:![0-9]+]]
// O2-NEXT:    store i64 [[TMP0]], ptr [[OUT]], align 8, !tbaa [[LONG_TBAA9:![0-9]+]]
// O2-NEXT:    call void @observe(ptr noundef nonnull [[OUT]]) #[[ATTR3]]
// O2-NEXT:    [[TMP1:%.*]] = load i64, ptr [[OUT]], align 8, !tbaa [[LONG_TBAA9]]
// O2-NEXT:    call void @llvm.lifetime.end.p0(ptr nonnull [[OUT]]) #[[ATTR3]]
// O2-NEXT:    ret i64 [[TMP1]]
//
// O0-LABEL: define dso_local i64 @test_rm_output_escapes(
// O0-SAME: ) #[[ATTR0]] {
// O0-NEXT:  [[ENTRY:.*:]]
// O0-NEXT:    [[OUT:%.*]] = alloca i64, align 8
// O0-NEXT:    call void asm sideeffect "# $0", "=*rm,~{dirflag},~{fpsr},~{flags}"(ptr elementtype(i64) [[OUT]]) #[[ATTR2]], !srcloc [[META3:![0-9]+]]
// O0-NEXT:    call void @observe(ptr noundef [[OUT]])
// O0-NEXT:    [[TMP0:%.*]] = load i64, ptr [[OUT]], align 8
// O0-NEXT:    ret i64 [[TMP0]]
//
unsigned long test_rm_output_escapes(void) {
  unsigned long out;
  __asm__ volatile("# %0" : "=rm"(out));
  observe(&out);
  return out;
}
